-- 62 tickers. bars (k=bar) and stored rows (k=row) for the #697 deeper replay. READ-ONLY.
SELECT 'bar' k, ticker, trade_date::text d, open_price::text a, high_price::text b, low_price::text c, close::text e, volume::text f FROM mi_daily_closes WHERE ticker IN ('ABCL','ABSI','ABVX','AGL','AMBQ','AMLX','AMPL','APPN','APPS','ATAI','BB','BFLY','BWIN','CAI','CHPT','CHYM','CRWD','DDOG','DELL','DFTX','EFOR','ETON','FBRX','FIVN','FWDI','GFS','GH','GSHD','HELP','HTFL','IMMX','LIFE','MBX','MRNA','NEO','NWL','OKTA','OMER','PAY','PBF','PGEN','PLSE','RBRK','REPL','RUM','SDGR','SLN','SLS','SMJF','TEM','TJGC','TRAX','TWLO','TXG','VCYT','VOYG','WDAY','WNC','XHLD','XMTR','XNCR','ZBIO') AND trade_date >= '2025-08-01' AND open_price IS NOT NULL ORDER BY ticker, trade_date;
SELECT 'row' k, ticker, scan_date::text d, stage a, COALESCE(held_from_stage,'') b, COALESCE(reason,'') c, COALESCE(pivot_high_date::text,'') e, COALESCE(pivot_high_price::text,'') f FROM mi_flag_candidates WHERE ticker IN ('ABCL','ABSI','ABVX','AGL','AMBQ','AMLX','AMPL','APPN','APPS','ATAI','BB','BFLY','BWIN','CAI','CHPT','CHYM','CRWD','DDOG','DELL','DFTX','EFOR','ETON','FBRX','FIVN','FWDI','GFS','GH','GSHD','HELP','HTFL','IMMX','LIFE','MBX','MRNA','NEO','NWL','OKTA','OMER','PAY','PBF','PGEN','PLSE','RBRK','REPL','RUM','SDGR','SLN','SLS','SMJF','TEM','TJGC','TRAX','TWLO','TXG','VCYT','VOYG','WDAY','WNC','XHLD','XMTR','XNCR','ZBIO') AND scan_date >= '2026-07-01' ORDER BY ticker, scan_date;
